solution.solution.cpp:
class Temperature
{
public:
    static Temperature fromCelsius(double c) { return Temperature{ c + 273.15 }; }
    static Temperature fromFahrenheit(double f) { return Temperature{ (f - 32.0) * 5.0 / 9.0 + 273.15 }; }

    double kelvin() const { return m_kelvin; }
    double celsius() const { return m_kelvin - 273.15; }
    double fahrenheit() const { return (m_kelvin - 273.15) * 9.0 / 5.0 + 32.0; }

private:
    explicit Temperature(double kelvin) : m_kelvin{ kelvin } {}
    double m_kelvin{};
};

unitTests:
static_assert(!std::is_constructible_v<Temperature, double>, "the constructor should be private: build temperatures through the factories");

TEST("fromCelsius") { const auto t{ Temperature::fromCelsius(25.0) }; CHECK_NEAR(t.kelvin(), 298.15, 1e-9); CHECK_NEAR(t.celsius(), 25.0, 1e-9); CHECK_NEAR(t.fahrenheit(), 77.0, 1e-9); }
TEST("fromFahrenheit") { const auto t{ Temperature::fromFahrenheit(212.0) }; CHECK_NEAR(t.celsius(), 100.0, 1e-9); CHECK_NEAR(t.kelvin(), 373.15, 1e-9); }
TEST("the two scales agree at -40") { CHECK_NEAR(Temperature::fromCelsius(-40.0).fahrenheit(), -40.0, 1e-9); }

